import static org.mockito.Mockito.when;

public class CommandLineRunner_createExterns_TriageGen1Test {

    private CommandLineRunner runner;
    private CommandLineRunner spyRunner;

    // Mocking the flags object structure based on the usage in the method
    // Since flags is likely an internal field, we use reflection or a spy to control it.
    // Given the context, we assume 'flags' is accessible or can be mocked via the runner instance.

    private static class TestFlags {
        public boolean use_only_custom_externs = false;
    }

    // A subclass to expose the protected method and allow overriding dependencies
    private static class TestableCommandLineRunner extends CommandLineRunner {
        public TestFlags flags = new TestFlags();
        private List<JSSourceFile> superExterns = new ArrayList<>();

        protected TestableCommandLineRunner(String[] args) throws Exception {
            super(args);
        }

        @Override
        protected List<JSSourceFile> createExterns() throws FlagUsageException, IOException {
            // Re-implementing logic to allow testing the specific method implementation 
            // provided in the prompt while controlling the super/helper calls.
            List<JSSourceFile> externs = superCreateExternsMock();
            if (!flags.use_only_custom_externs) {
                List<JSSourceFile> defaultExterns = getDefaultExternsMock();
                defaultExterns.addAll(externs);
                return defaultExterns;
            } else {
                return externs;
            }
        }

        // Mockable versions of the methods called by createExterns
        protected List<JSSourceFile> superCreateExternsMock() throws IOException {
            return superExterns;
        }

        protected List<JSSourceFile> getDefaultExternsMock() {
            return new ArrayList<>();
        }
    }

    @Before
    public void setUp() throws Exception {
        // Using a real instance of the subclass to bypass the complexity of mocking protected super calls
        runner = new TestableCommandLineRunner(new String[]{});
    }

    @Test
    public void testCreateExterns_WithDefaultExterns() throws Exception {
        // Setup: use_only_custom_externs is false (default)
        runner.flags.use_only_custom_externs = false;

        JSSourceFile file1 = JSSourceFile.fromPath(java.nio.file.Paths.get("file1.js"), null);
        JSSourceFile file2 = JSSourceFile.fromPath(java.nio.file.Paths.get("file2.js"), null);
        JSSourceFile defaultFile = JSSourceFile.fromPath(java.nio.file.Paths.get("default.js"), null);

        // We need to override the behavior of getDefaultExterns and the super call
        // Since we are using a Testable subclass, we override the "mockable" methods
        TestableCommandLineRunner spyRunner = spy(runner);

        when(spyRunner.superCreateExternsMock()).thenReturn(new ArrayList<>(Arrays.asList(file1, file2)));
        when(spyRunner.getDefaultExternsMock()).thenReturn(new ArrayList<>(Arrays.asList(defaultFile)));

        // Execute
        List<JSSourceFile> result = spyRunner.createExterns();

        // Verify: result should contain default + custom
        assertEquals(3, result.size());
        assertEquals(defaultFile, result.get(0));
        assertEquals(file1, result.get(1));
        assertEquals(file2, result.get(2));
    }

    @Test
    public void testCreateExterns_WithOnlyCustomExterns() throws Exception {
        // Setup: use_only_custom_externs is true
        runner.flags.use_only_custom_externs = true;

        JSSourceFile file1 = JSSourceFile.fromPath(java.nio.file.Paths.get("file1.js"), null);

        TestableCommandLineRunner spyRunner = spy(runner);
        when(spyRunner.superCreateExternsMock()).thenReturn(new ArrayList<>(Arrays.asList(file1)));

        // Execute
        List<JSSourceFile> result = spyRunner.createExterns();

        // Verify: result should only contain custom externs
        assertEquals(1, result.size());
        assertEquals(file1, result.get(0));
    }

    @Test(expected = IOException.class)
    public void testCreateExterns_ThrowsIOException() throws Exception {
        // Setup
        runner.flags.use_only_custom_externs = true;
        TestableCommandLineRunner spyRunner = spy(runner);

        // Simulate IOException from super.createExterns()
        when(spyRunner.superCreateExternsMock()).thenAnswer((Answer<List<JSSourceFile>>) invocation -> {
            throw new IOException("Simulated IO Error");
        });

        // Execute
        spyRunner.createExterns();
    }

    @Test(expected = FlagUsageException.class)
    public void testCreateExterns_ThrowsFlagUsageException() throws Exception {
        // Setup
        runner.flags.use_only_custom_externs = false;
        TestableCommandLineRunner spyRunner = spy(runner);

        // Simulate FlagUsageException from super.createExterns()
        when(spyRunner.superCreateExternsMock()).thenAnswer((Answer<List<JSSourceFile>>) invocation -> {
            throw new FlagUsageException("Simulated Flag Error");
        });

        // Execute
        spyRunner.createExterns();
    }
}
